n-oficial-editor" name="confirmar" value="1" required> Revisé composición, precio y todos los negocios afectados</label><button class="admin-btn admin-btn--primary" form="presentacion-oficial-editor" name="accion" value="publicar">Publicar nueva versión oficial</button><?php endif; ?></div><?php endif; endif; ?></section>
